cat > Api.Tests/PayByCardSteps.cs <<'E'
using Reqnroll;
using Xunit;

namespace Api.Tests;

[Binding]
public class PayByCardSteps
{
    private int _accepted;
    private int _basket;

    [Given("a returning customer with a valid card")]
    public void GivenAReturningCustomerWithAValidCard() { }

    [When("a basket of {int} cents is paid")]
    public void WhenABasketIsPaid(int cents) { _basket = cents; _accepted = cents; }

    [Then("the payment is accepted for {int} cents")]
    public void ThenThePaymentIsAccepted(int cents)
    {
        Assert.Equal(cents, _accepted);
        Assert.Equal(_basket, _accepted);
    }
}
